void ProjectStateDocument::append_chat_record(const std::string& conversation_id, const std::string& format,
                                              const std::vector<RecordItem>& items)
{
    json* conversation = conversation_json(conversation_id);
    if (!conversation || format.empty())
        throw std::logic_error("a record in no format, or for a chat the document does not hold");
    if (conversation->contains("record") && conversation->at("record").at("format") != format)
        throw std::logic_error("a chat recorded in " + conversation->at("record").at("format").get<std::string>() +
                               " cannot take items in " + format);
    json entries = json::array();
    for (const RecordItem& item : items)
        entries.push_back(record_item_json(item));
    json& stored = (*conversation)["record"];
    if (stored.is_null())
        stored = json{{"format", format}, {"items", json::array()}, {"migrated", json::array()}};
    for (json& entry : entries)
        stored["items"].push_back(std::move(entry));
    touch();
}

void ProjectStateDocument::start_chat_record(const std::string& conversation_id, const std::string& format,
                                             const std::vector<RecordItem>& items, const std::vector<std::string>& migrated)
{
    json* conversation = conversation_json(conversation_id);
    if (!conversation || conversation->contains("record") || format.empty())
        throw std::logic_error("a chat record is started once, in a format, for a chat the document holds");
    json entries = json::array();
    for (const RecordItem& item : items)
        entries.push_back(record_item_json(item));
    (*conversation)["record"] = json{{"format", format}, {"items", std::move(entries)}, {"migrated", migrated}};
    touch();
}

