std::optional<AgentError> AgentHost::record_refusal(const std::string& conversation_id, const ChatModelChoice& choice) const
{
    const std::optional<ChatRecord> record = m_persistence.document().chat_record(conversation_id);
    const ProviderProfile*          row    = profile_for(choice.provider);
    if (!record || record->format.empty() || row == nullptr)
        return std::nullopt;
    // An account's model is served in the format its list names; one not
    // named yet is checked again when the chat next sends.
    const std::string format = row->account_sign_in ?
                                   (choice.format.empty() ? m_model_source->model_format(choice.provider, choice.model) : choice.format) :
                                   wire_format(row->family);
    const bool clears = std::any_of(record->items.begin(), record->items.end(), [](const RecordItem& item) { return item.clears; });
    if ((format.empty() || format == record->format) && (!clears || clears_skills(*row)))
        return std::nullopt;
    return AgentError{"chat_format_fixed",
                      "This chat's history is kept in a form that model can't read. Start a new chat to use it.", false};
}

