// messages the first time it talks again: the person's words and the replies
// as plain text, once, in the format of the provider the chat talks to.
// Nothing else of it was kept, and nothing is made up.
TEST_CASE("a chat from before the record sends its earlier words once, as plain text", "[agent][record]")
{
    for (const WireFormat& wire : {anthropic_wire(), responses_wire()}) {
        DYNAMIC_SECTION(wire.provider)
        {
            PrefixChat chat(wire);
            chat.person_turn("Is PLA fine for a bracket?", {{"PLA is fine."}});
            ProjectStateDocument& document = chat.harness->persistence.document();
            const std::string id = document.active_conversation_id();
            const std::vector<ConversationMessage> earlier = document.messages(id);
            REQUIRE(earlier.size() == 2);
            // As a document written before the record existed: its messages only.
            json saved = json::parse(document.dump());
            for (json& conversation : saved["conversations"])
                conversation.erase("record");
            REQUIRE(document.load(saved.dump()) == ProjectStateDocument::LoadResult::Loaded);
            REQUIRE_FALSE(document.chat_record(id));

            chat.person_turn("And for a hook?", {{"PETG is better for a hook."}});
            const std::string& first = chat.provider->replies.back();
            CHECK(occurrences(first, "Is PLA fine for a bracket?") == 1);
            CHECK(occurrences(first, "PLA is fine.") == 1);
            const std::optional<ChatRecord> record = document.chat_record(id);
            REQUIRE(record);
            CHECK(record->format == (wire.provider == "anthropic" ? "anthropic" : "responses"));
            CHECK(record->migrated == std::vector<std::string>{earlier[0].id, earlier[1].id});
            REQUIRE(record->items.size() == 4);
            CHECK(record->items[0].source.empty());
            CHECK(record->items[0].parts.at(0).text == "Is PLA fine for a bracket?");
            CHECK(record->items[1].output.is_null());
            CHECK(record->items[1].text == "PLA is fine.");

            // The next turn opens with the plain start and what the last turn sent.
            chat.person_turn("Thanks.", {{"You are welcome."}});
            check_opens_with(prompt_of(wire, chat.provider->replies[1]), prompt_of(wire, chat.provider->replies[2]));
        }
    }
}

// What a request carried joins the chat's record once the provider takes it.
// A refused request leaves nothing behind, whether the service was down or
// would never take it (a picture too large): the person's message goes again
// with the next turn, once.
TEST_CASE("a request the provider refuses leaves nothing in the chat's record", "[agent][record]")
{
    const unsigned status = GENERATE(503u, 400u, 413u);
    for (const WireFormat& wire : {anthropic_wire(), responses_wire()}) {

            chat.turn({{"Done."}}, [&] { chat.harness->deliver("retry_message", json{{"messageId", failed}}); });
            const Prompt broken  = prompt_of(wire, chat.provider->replies[1]);
            const Prompt retried = prompt_of(wire, chat.provider->replies[2]);
            CHECK(retried.rest == broken.rest);
            CHECK(retried.parts == broken.parts);
            CHECK(chat.provider->replies[2].find("Half an ans") == std::string::npos);
        }
    }
}

// A note the app rewrites after the model read it (a receipt's Undo) is news
// whichever turn comes next: it goes again as it reads now, once.
TEST_CASE("a note the app rewrote after the model read it goes again with the next turn, once", "[agent][record]")
{
    auto            agent_owner = std::make_unique<RecordingAgent>();
    RecordingAgent* agent       = agent_owner.get();
    Harness         harness{AgentServicePtr(std::move(agent_owner))};
    harness.handshake();
    const std::string note_id = harness.host.post_note("The slice finished.");
    harness.pump_all();
    harness.send_user_message("Thanks.", "c-1");
    harness.pump_all();
    const auto operator_texts = [](const AgentRequest& request) {
        std::vector<std::string> texts;
        for (const RecordItem& item : request.unsent)
            if (item.kind == RecordItem::Kind::Operator)
                texts.push_back(item.text);
        return texts;
    };
    CHECK(operator_texts(last_reply(agent->requests)) == std::vector<std::string>{"The slice finished."});

    ProjectStateDocument& document = harness.persistence.document();
    const std::string     chat     = document.active_conversation_id();
    for (ConversationMessage message : document.messages(chat))
        if (message.id == note_id) {
            message.for_model = "The slice was undone.";
            document.update_message(chat, message);
        }
    harness.send_user_message("And now?", "c-2");
    harness.pump_all();
    CHECK(operator_texts(last_reply(agent->requests)) == std::vector<std::string>{"The slice was undone."});
    harness.send_user_message("Ok.", "c-3");
    harness.pump_all();
    CHECK(operator_texts(last_reply(agent->requests)).empty());
}

